export function art(file){
  if(file.image)return `<img src="assets/${file.image}" alt="${file.name} ${file.kind==='rhino'?'chair render':file.kind==='blender'?'glass sculpture':'mountain landscape'}" draggable="false">`;
  if(file.kind==='illustrator')return '<div class="poster" aria-hidden="true"><div class="poster-top"><span>FORM STUDIES</span><span>026</span></div><div class="poster-title">OFF<br>/ GRID</div><i class="poster-orbit"></i><i class="poster-orbit o2"></i><i class="poster-orbit o3"></i><div class="poster-bottom">A STUDY IN MOVEMENT<br>AND EVERYTHING BETWEEN.</div></div>';
  if(file.kind==='figma')return '<div class="figma-art" aria-hidden="true"><div class="mock-browser"><div class="browser-top"><b>unwind®</b><span>Spaces &nbsp; Stories &nbsp; About</span></div><div class="mock-title">A slower way<br>to <em>find yourself.</em></div><div class="mock-photo"></div><div class="mock-bottom"><span></span><span></span><span></span></div></div></div>';
  if(file.kind==='indesign')return '<div class="editorial" aria-hidden="true"><div class="editorial-head">Field<br>notes.</div><div class="editorial-sub">OBSERVATIONS FROM ELSEWHERE</div><div class="editorial-body"><img src="assets/landscape.webp" alt="" draggable="false"><div class="editorial-lines"></div></div></div>';
  return '<div class="film-art" aria-hidden="true"><img src="assets/landscape.webp" alt="" draggable="false"><span class="film-timecode">00:01:24:08 &nbsp; • &nbsp; 24 FPS</span><div class="film-timeline"><div class="film-track"></div><div class="film-track"></div><div class="film-track"></div></div></div>';
}
